CREATE OR REPLACE FUNCTION public.team_works_save_partner_student_handoff(p_roster_id uuid, p_attendance_status text, p_assessment jsonb, p_handoff_note text, p_complete boolean DEFAULT false)
 RETURNS TABLE(current_manual_no integer, completed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_roster public.team_works_session_roster%rowtype;
  target_session public.team_works_op_sessions%rowtype;
  worker_member_id uuid;
  completed_now boolean := false;
begin
  if p_attendance_status not in ('scheduled', 'present', 'absent', 'late', 'excused') then
    raise exception 'Unsupported attendance status';
  end if;

  if p_assessment is null or jsonb_typeof(p_assessment) <> 'object' then
    raise exception 'Assessment must be an object';
  end if;

  if length(coalesce(p_handoff_note, '')) > 4000 then
    raise exception 'Handoff note is too long';
  end if;

  select *
    into target_roster
  from public.team_works_session_roster
  where id = p_roster_id
  for update;

  if target_roster.id is null then
    raise exception 'Roster row not found';
  end if;

  select *
    into target_session
  from public.team_works_op_sessions
  where id = target_roster.session_id
    and status <> 'cancelled';

  select pm.organization_member_id
    into worker_member_id
  from public.team_works_project_members pm
  join public.team_works_organization_members om
    on om.id = pm.organization_member_id
  where pm.project_id = target_roster.project_id
    and pm.project_role = 'worker'
    and om.user_id = (select auth.uid())
    and om.status = 'active'
  limit 1;

  if worker_member_id is null or target_session.partner_member_id is distinct from worker_member_id then
    raise exception 'You are not assigned to this session';
  end if;

  completed_now := p_complete and target_roster.partner_completed_at is null;

  update public.team_works_session_roster
  set attendance_status = p_attendance_status,
      partner_assessment = p_assessment,
      handoff_note = nullif(trim(coalesce(p_handoff_note, '')), ''),
      partner_completed_at = case
        when completed_now then now()
        else partner_completed_at
      end,
      updated_at = now()
  where id = p_roster_id;

  if completed_now then
    update public.team_works_participants as participant
    set current_manual_no = participant.current_manual_no + 1,
        updated_at = now()
    where participant.id = target_roster.participant_id;
  end if;

  return query
  select participant.current_manual_no, roster.partner_completed_at
  from public.team_works_participants participant
  join public.team_works_session_roster roster on roster.id = p_roster_id
  where participant.id = target_roster.participant_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.team_works_update_partner_presence(p_session_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  target_session public.team_works_op_sessions%rowtype;
  worker_member_id uuid;
begin
  if p_status not in ('not_started', 'standby', 'in_progress', 'ended') then
    raise exception 'Unsupported partner presence status';
  end if;

  select *
    into target_session
  from public.team_works_op_sessions
  where id = p_session_id
    and status <> 'cancelled';

  if target_session.id is null then
    raise exception 'Session not found';
  end if;

  select pm.organization_member_id
    into worker_member_id
  from public.team_works_project_members pm
  join public.team_works_organization_members om
    on om.id = pm.organization_member_id
  where pm.project_id = target_session.project_id
    and pm.project_role = 'worker'
    and om.user_id = (select auth.uid())
    and om.status = 'active'
  limit 1;

  if worker_member_id is null or target_session.partner_member_id is distinct from worker_member_id then
    raise exception 'You are not assigned to this session';
  end if;

  update public.team_works_op_sessions
  set partner_presence_status = p_status,
      partner_standby_at = case
        when p_status = 'not_started' then null
        when p_status in ('standby', 'in_progress') then coalesce(partner_standby_at, now())
        else partner_standby_at
      end,
      partner_ended_at = case when p_status = 'ended' then now() else null end,
      updated_at = now()
  where id = p_session_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.team_works_update_session_zoom(p_session_id uuid, p_use_project_default boolean, p_zoom_url text DEFAULT NULL::text, p_zoom_meeting_id text DEFAULT NULL::text, p_zoom_passcode text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_project_id uuid;
  v_organization_id uuid;
  v_partner_member_id uuid;
  v_session_date date;
  v_worker_member_id uuid;
  v_zoom_url text := nullif(btrim(p_zoom_url), '');
  v_zoom_meeting_id text := nullif(btrim(p_zoom_meeting_id), '');
  v_zoom_passcode text := nullif(btrim(p_zoom_passcode), '');
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select s.project_id, p.organization_id, s.partner_member_id, s.session_date
    into v_project_id, v_organization_id, v_partner_member_id, v_session_date
  from public.team_works_op_sessions s
  join public.team_works_projects p on p.id = s.project_id
  where s.id = p_session_id
    and p.style = 'operations';

  if v_project_id is null then
    raise exception 'Session not found';
  end if;
  if v_session_date < current_date then
    raise exception 'Past session Zoom settings cannot be changed';
  end if;

  v_worker_member_id :=
    private.team_works_project_member_id_for(v_project_id, 'worker');

  if not private.team_works_is_org_staff(v_organization_id)
     and (v_worker_member_id is null or v_partner_member_id <> v_worker_member_id) then
    raise exception 'Not authorized to update this session Zoom setting';
  end if;

  if coalesce(p_use_project_default, false) then
    select p.zoom_url, p.zoom_meeting_id, p.zoom_passcode
      into v_zoom_url, v_zoom_meeting_id, v_zoom_passcode
    from public.team_works_projects p
    where p.id = v_project_id;
  end if;

  update public.team_works_op_sessions
  set zoom_url = v_zoom_url,
      zoom_meeting_id = v_zoom_meeting_id,
      zoom_passcode = v_zoom_passcode,
      zoom_uses_project_default = coalesce(p_use_project_default, false),
      updated_at = now()
  where id = p_session_id;
end;
$function$
